AWS API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS API Gateway container

Container_Boundary(aws_api_gateway, "AWS API Gateway") {
    Component(RequestValidator, "Request Validator", "AWS API Gateway native Request Validator", "Validates incoming JSON schema for payment authorization requests.")
    Component(Authorizer, "Authorizer", "AWS API Gateway Authorizer (mTLS)", "Handles mTLS authorization for external payment gateway and acquirer systems.")
    Component(HttpProxyIntegration, "HTTP Proxy Integration", "VPC Link / HTTP Proxy", "Routes validated requests to the Scoring Engine over internal VPC Links.")
}

Rel(RequestValidator, Authorizer, "Validates request payloads after authorization", "")
Rel(Authorizer, HttpProxyIntegration, "Passes authenticated requests for routing", "")

@enduml

Amazon DynamoDB.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon DynamoDB container

System_Ext(ScoringEngine, "Scoring Engine", "Go, AWS ECS Fargate", "Evaluates card-not-present payment authorizations.")
System_Ext(CaseManagementBackend, "Case Management Backend", "Node.js/Go, AWS ECS Fargate", "Manages analyst workflow state.")

Container_Boundary(AmazonDynamoDB, "Amazon DynamoDB") {
    Component(FraudRulesTable, "FraudRulesTable", "Amazon DynamoDB (Single-table design with composite primary keys RuleType, RuleID)", "Stores rule and model state for sub-50ms rule retrieval by the Scoring Engine.")
    Component(CaseManagementTable, "CaseManagementTable", "Amazon DynamoDB", "Stores analyst workflow state accessed by the Case Management Backend.")
}

Rel(ScoringEngine, FraudRulesTable, "Reads and writes rule/model state via AWS SDK / HTTPS (TCP 443) using Consistent Read", "AWS SDK / HTTPS (TCP 443)")
Rel(CaseManagementBackend, CaseManagementTable, "Reads and writes analyst workflow state via AWS SDK / HTTPS (TCP 443)", "AWS SDK / HTTPS (TCP 443)")
@enduml

Amazon Kinesis Data Firehose.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Boundary(amazon_kinesis_data_firehose, "Amazon Kinesis Data Firehose") {
    Component(Firehose_Buffer_Manager, "Firehose Buffer Manager", "Amazon Kinesis Data Firehose Native", "Batches incoming audit logs before sending them for transformation.")
    Component(Firehose_Data_Transformer, "Firehose Data Transformer", "AWS Lambda", "Sanitizes audit logs natively before persistence.")
    Component(S3_Delivery_Stream_Writer, "S3 Delivery Stream Writer", "Amazon Kinesis Data Firehose Native", "Writes immutable log batches to storage.")
}

System_Ext(Amazon_S3_Object_Lock, "Amazon S3 Object Lock", "Enforces WORM storage for auditability")

Rel(Firehose_Buffer_Manager, Firehose_Data_Transformer, "Invokes record transformation", "AWS Lambda API")
Rel(S3_Delivery_Stream_Writer, Amazon_S3_Object_Lock, "Writes immutable log batches with SSE-KMS", "AWS S3 API")
@enduml

Amazon S3 Object Lock.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Amazon_S3_Object_Lock, "Amazon S3 Object Lock") {
    Component(S3_Bucket_with_Object_Lock, "S3 Bucket with Object Lock", "AWS S3 Bucket with Object Lock (Compliance Mode)", "Stores immutable audit logs enforcing 7-year retention.")
    Component(Bucket_Lifecycle_Policy_Manager, "Bucket Lifecycle Policy Manager", "AWS S3 Lifecycle", "Manages object lifecycle and retention policies.")
    Component(AWS_KMS_Encryption_Key, "AWS KMS Encryption Key", "AWS KMS", "Provides encryption and decryption for audit objects.")
}

Rel(S3_Bucket_with_Object_Lock, AWS_KMS_Encryption_Key, "Encrypts and decrypts audit objects", "AWS KMS API")
Rel(Bucket_Lifecycle_Policy_Manager, S3_Bucket_with_Object_Lock, "Applies retention and lifecycle rules", "AWS S3 Lifecycle")
